function RequestForm({kind,patient,onSubmit,onClose}){const isBlood=kind==='blood';const isEcho=kind==='echo';const tests=['U&Es','FBC','CRP','LFTs','Coagulation','Group and save','Blood cultures'];const [form,setForm]=useState({identity:patient.name,bed:String(patient.bed),clinical:'',question:'',test:'',selected:[]});const change=(k,v)=>setForm(x=>({...x,[k]:v}));const toggle=t=>setForm(x=>({...x,selected:x.selected.includes(t)?x.selected.filter(z=>z!==t):[...x.selected,t]}));const ready=isBlood?form.selected.length>0:form.test.trim()&&form.clinical.trim().length>=15&&form.question.trim().length>=10;return <div className="form-shade"><form className="request-sheet" onSubmit={e=>{e.preventDefault();if(ready)onSubmit({...form,test:isBlood?form.selected.join(', '):form.test})}}><div className="request-title"><h2>{isBlood?'🧪 Blood request':isEcho?'🫀 Echocardiography request':'🩻 Radiology request'}</h2><button type="button" onClick={onClose}>✕</button></div><p><b>{patient.name}</b> · Bed {patient.bed}</p>{isBlood?<><p>Select the blood tests to collect. Results are released only after venepuncture is completed.</p><div className="request-grid">{tests.map(t=><label key={t}><input type="checkbox" checked={form.selected.includes(t)} onChange={()=>toggle(t)}/> {t}</label>)}</div></>:<><label>Examination / views<input value={form.test} onChange={e=>change('test',e.target.value)} placeholder="e.g. Chest X-ray, PA erect"/></label><label>Clinical history and examination<textarea rows="3" value={form.clinical} onChange={e=>change('clinical',e.target.value)} placeholder="Symptoms, duration, relevant findings and observations"/></label><label>Clinical question<textarea rows="2" value={form.question} onChange={e=>change('question',e.target.value)} placeholder="What should radiology assess?"/></label></>}<div className="action-row"><button type="button" onClick={onClose}>Cancel</button><button className="primary" disabled={!ready}>Submit for review →</button></div></form></div>}
function PrescriptionChart({kind,patient,onSubmit,onClose}){const [v,setV]=useState({drug:'',dose:'',route:kind==='antibiotic'?'Oral':'IV',frequency:'',duration:'',fluid:'',volume:'',time:'',allergy:'',weight:''});const set=(k,x)=>setV(a=>({...a,[k]:x}));const antibiotic=kind==='antibiotic';const valid=antibiotic?v.drug.trim()&&v.dose.trim()&&v.route&&v.frequency.trim()&&v.duration.trim()&&v.allergy.trim():v.fluid.trim()&&Number(v.volume)>0&&v.time.trim()&&v.route&&v.weight.trim();return <div className="form-shade"><form className="request-sheet" onSubmit={e=>{e.preventDefault();if(valid)onSubmit(v)}}><div className="request-title"><h2>{antibiotic?'💊 Antimicrobial prescription':'💧 IV fluid prescription'}</h2><button type="button" onClick={onClose}>✕</button></div><p><b>{patient.name}</b> · Bed {patient.bed}. Enter an actual prescription, not simply “give antibiotics” or “give fluids”.</p>{antibiotic?<><label>Allergy status (and reaction, if any)<input value={v.allergy} onChange={e=>set('allergy',e.target.value)} placeholder="e.g. no known drug allergies"/></label><label>Choose antibiotic<select value={v.drug} onChange={e=>set('drug',e.target.value)}><option value="">Select an antibiotic…</option>{["Amoxicillin","Doxycycline","Clarithromycin","Co-amoxiclav","Ceftriaxone"].map(d=><option key={d} value={d}>{d}</option>)}</select></label><div className="request-grid"><label>Dose<input value={v.dose} onChange={e=>set('dose',e.target.value)} placeholder="e.g. 500 mg"/></label><label>Route<select value={v.route} onChange={e=>set('route',e.target.value)}><option>Oral</option><option>IV</option></select></label><label>Frequency<input value={v.frequency} onChange={e=>set('frequency',e.target.value)} placeholder="e.g. three times daily"/></label><label>Duration / review date<input value={v.duration} onChange={e=>set('duration',e.target.value)} placeholder="e.g. review in 48 hours"/></label></div></>:<><label>Patient weight (kg)<input value={v.weight} onChange={e=>set('weight',e.target.value)} placeholder="72 kg (given by nurse)"/></label><label>Fluid type<input value={v.fluid} onChange={e=>set('fluid',e.target.value)} placeholder="e.g. sodium chloride 0.9%"/></label><div className="request-grid"><label>Volume (mL)<input type="number" min="1" value={v.volume} onChange={e=>set('volume',e.target.value)}/></label><label>Infusion duration (hours)<input value={v.time} onChange={e=>set('time',e.target.value)} placeholder="e.g. 1"/></label></div><p className="muted">Check observations, renal function, electrolytes, fluid balance and local HHS guidance before prescribing.</p></>}<div className="action-row"><button type="button" onClick={onClose}>Cancel</button><button className="primary" disabled={!valid}>Review prescription →</button></div></form></div>}
