function WalkWard({patients,pending,done,avatar,clock,minute,onBed,onStation}){
 const W=18,H=16, [pos,setPos]=useState({x:8,y:13}),[facing,setFacing]=useState('up'),[npc,setNpc]=useState(0),[message,setMessage]=useState('Walk with WASD or arrow keys. Press E near a bed or nurse.'),[target,setTarget]=useState(null);
 const beds=patients.map((p,i)=>({...p,x:i<5?2:14,y:3+(i%5)*2}));
 const blocked=(x,y)=>x<1||x>=W-1||y<2||y>=H-1||beds.some(b=>Math.abs(b.x-x)<2&&b.y===y)||(x>=7&&x<=10&&y===3);
 const near=(x,y,b)=>Math.abs(x-b.x)+Math.abs(y-b.y)<=2;
 const interact=()=>{const b=beds.find(b=>near(pos.x,pos.y,b));if(b){onBed(b.bed);return}if(Math.abs(pos.x-9)+Math.abs(pos.y-3)<=3){onStation();return}setMessage('Move closer to a bed or the nurses’ station to interact.')};
 const step=(dx,dy)=>{setFacing(dx>0?'right':dx<0?'left':dy<0?'up':'down');setPos(p=>{let x=p.x+dx,y=p.y+dy;return blocked(x,y)?p:{x,y}})};
 const interactRef=useRef(interact),stepRef=useRef(step);interactRef.current=interact;stepRef.current=step;
 useEffect(()=>{const handler=e=>{if(e.target.closest('input,textarea,select,button'))return;const k=e.key.toLowerCase();const d={arrowup:[0,-1],w:[0,-1],arrowdown:[0,1],s:[0,1],arrowleft:[-1,0],a:[-1,0],arrowright:[1,0],d:[1,0]}[k];if(d){e.preventDefault();stepRef.current(...d)}else if(k==='e'||k==='enter'){e.preventDefault();interactRef.current()}};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler)},[]);
 useEffect(()=>{const t=setInterval(()=>setNpc(n=>n+1),1300);return()=>clearInterval(t)},[]);
 useEffect(()=>{if(!target)return;const t=setInterval(()=>setPos(p=>{if(Math.abs(p.x-target.x)+Math.abs(p.y-target.y)<=2){setTarget(null);onBed(target.bed);return p}let opts=[[Math.sign(target.x-p.x),0],[0,Math.sign(target.y-p.y)],[-Math.sign(target.x-p.x),0],[0,-Math.sign(target.y-p.y)]];opts.sort((a,b)=>Math.abs(target.x-(p.x+a[0]))+Math.abs(target.y-(p.y+a[1]))-Math.abs(target.x-(p.x+b[0]))-Math.abs(target.y-(p.y+b[1])));const valid=opts.find(([dx,dy])=>(dx||dy)&&!blocked(p.x+dx,p.y+dy));return valid?{x:p.x+valid[0],y:p.y+valid[1]}:p}),140);return()=>clearInterval(t)},[target]);
 const tile=(x,y)=>({left:`${x/W*100}%`,top:`${y/H*100}%`});
 return <div className="rpg-wrap"><div className="rpg-top"><b>🏥 MediWard · Ward 1</b><span>🕒 {clock} {minute>=540?'🌙':'☀️'}</span><span>🎮 WASD / arrows · E to talk</span></div><div className="rpg-world" tabIndex={0} aria-label="Walkable ward map">
 {Array.from({length:W*H},(_,i)=>{const x=i%W,y=Math.floor(i/W);return <div key={i} className={'rpg-tile '+(y<2?'rpg-wall':(x+y)%2?'rpg-floor-a':'rpg-floor-b')} style={tile(x,y)}>{y===1&&(x===2||x===15)?'🪟':null}</div>})}
 <div className="rpg-decor" style={{...tile(9,1),width:'15%'}}>🕒 {clock}</div>
 <button className="rpg-station" style={{...tile(7,3),width:`${4/W*100}%`}} onClick={onStation}>💻<small>NURSES' STATION · E</small></button>
 {beds.map(b=><button key={b.bed} className={'rpg-bed '+(pending===b.bed?'rpg-alert':'')} style={{...tile(b.x,b.y),width:`${2/W*100}%`,height:`${1/H*100}%`}} onClick={()=>{if(pending===b.bed){setTarget(null);onBed(b.bed)}else{setTarget(b);setMessage(`Walking to Bed ${b.bed}…`)}}} title={`Bed ${b.bed} · ${b.name}`}><span className="rpg-bednum">{b.bed}</span><span className="rpg-face">{b.avatar}</span><span className="rpg-blanket"/><small>{b.name.split(' ')[0]} {done.includes(b.bed)?'✓':''}</small></button>)}
 <button className="rpg-npc" style={tile(6+Math.round(Math.sin(npc*.6)*2),6+Math.round(Math.cos(npc*.4)*2))} onClick={onStation}>👩🏾‍⚕️<small>Aisha</small></button>
 <button className="rpg-npc" style={tile(11+Math.round(Math.sin(npc*.5)*2),10+Math.round(Math.cos(npc*.5)*2))} onClick={onStation}>👨🏻‍⚕️<small>Oliver</small></button>
 <div className="rpg-player" style={tile(pos.x,pos.y)}>{avatar}<small>YOU {facing==='left'?'◀':facing==='right'?'▶':facing==='up'?'▲':'▼'}</small></div>
 {pending&&<div className="rpg-urgent-banner">🚨 NURSE: Doctor! Please come to Bed {pending} immediately!</div>}
 </div><div className="rpg-controls"><span>{message}</span><div className="rpg-pad"><button onClick={()=>step(0,-1)}>▲</button><div><button onClick={()=>step(-1,0)}>◀</button><button onClick={interact}>E · Talk</button><button onClick={()=>step(1,0)}>▶</button></div><button onClick={()=>step(0,1)}>▼</button></div></div></div>
}

function App(){const[mode,setMode]=useState('easy'),[started,setStarted]=useState(false),[minute,setMinute]=useState(0),[done,setDone]=useState([]),[rescued,setRescued]=useState([]),[grave,setGrave]=useState([]),[history,setHistory]=useState([]),[pending,setPending]=useState(null),[active,setActive]=useState(null),[tab,setTab]=useState('jobs'),[steps,setSteps]=useState({}),[stage,setStage]=useState(0),[assessed,setAssessed]=useState({}),[treated,setTreated]=useState(false),[log,setLog]=useState([]),[draft,setDraft]=useState(''),[sbar,setSbar]=useState(''),[reg,setReg]=useState(false),[station,setStation]=useState(false),[notice,setNotice]=useState(''),[mute,setMute]=useState(false),[listening,setListening]=useState(false),[request,setRequest]=useState(null),[procedures,setProcedures]=useState({}),[requests,setRequests]=useState({}),[prescription,setPrescription]=useState(null),[prescribed,setPrescribed]=useState({});const logEnd=useRef(null);const speech=useRef(null);const[avatar,setAvatar]=useState('👩🏽‍⚕️');const[completeAt,setCompleteAt]=useState(0);const[emIndex,setEmIndex]=useState(0);const [cooldown,setCooldown]=useState(false);const [shiftSeconds,setShiftSeconds]=useState(0);const [emDeadline,setEmDeadline]=useState(null);const [routineBleeps,setRoutineBleeps]=useState([]);const [nurseWarning,setNurseWarning]=useState('');const [copdStep,setCopdStep]=useState(0);const [socialTopics,setSocialTopics]=useState([]);const activePatient=active?patients[active.bed-1]:null;const event=active?.em?emergencies[active.bed]:null;const clock=`${String(8+Math.floor(minute/60)).padStart(2,'0')}:${String(minute%60).padStart(2,'0')}`;
function beep(){if(mute)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)();[0,.24,.48].forEach(delay=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='square';o.frequency.value=880;g.gain.value=.12;o.connect(g).connect(ctx.destination);o.start(ctx.currentTime+delay);o.stop(ctx.currentTime+delay+.16)});setTimeout(()=>ctx.close(),1100)}catch{}}
useEffect(()=>{if(!started)return;const t=setInterval(()=>setMinute(x=>Math.min(719,x+1)),1400);return()=>clearInterval(t)},[started]);
// Real-time shift timer: first urgent bleep at two minutes. Routine bleeps continue on hard mode.
useEffect(()=>{if(!started)return;const id=setInterval(()=>setShiftSeconds(t=>t+1),1000);return()=>clearInterval(id)},[started]);
useEffect(()=>{if(!started||mode!=='hard')return;const id=setInterval(()=>{const choices=patients.filter(p=>!done.includes(p.bed)&&p.bed!==pending);if(!choices.length)return;const p=choices[Math.floor(Math.random()*choices.length)];const messages=[`Nurse Aisha: Doctor, Bed ${p.bed} is still waiting for ${p.job.toLowerCase()}.`,`Nurse Oliver: Could you review Bed ${p.bed} when you have a moment?`,`Nurse Aisha: A reminder about ${p.name} in Bed ${p.bed}.`];setRoutineBleeps(q=>[{id:Date.now(),bed:p.bed,text:messages[Math.floor(Math.random()*messages.length)]},...q].slice(0,5));beepRoutine()},45000);return()=>clearInterval(id)},[started,mode,done,pending,mute]);
useEffect(()=>{if(!started||pending||active?.em||cooldown||emIndex>=emergencyOrder.length||shiftSeconds<120)return;if(emIndex>0&&done.length-completeAt<2)return;const bed=emergencyOrder[emIndex];setPending(bed);setEmDeadline(shiftSeconds+300);setNurseWarning('');setNotice(`🚨 URGENT BLEEP — Bed ${bed}: ${emergencies[bed].title}`);beep()},[started,pending,active,emIndex,shiftSeconds,cooldown,done.length,completeAt]);
useEffect(()=>{if(!pending||emDeadline===null)return;const remaining=emDeadline-shiftSeconds;if(remaining<=0){const bed=pending;setGrave(v=>v.includes(bed)?v:[...v,bed]);setHistory(v=>[{bed,type:'Emergency',outcome:'Not attended within five minutes — patient transferred to graveyard',time:clock},...v]);setNotice(`🪦 Bed ${bed}: the emergency was not attended within five minutes. Retry from the graveyard.`);setPending(null);setEmDeadline(null);setNurseWarning('');setEmIndex(v=>v+1);setCompleteAt(done.length);setCooldown(true);setTimeout(()=>setCooldown(false),12000);return}if(active?.em&&active.bed===pending)return;if(remaining<=270&&remaining%60===0){setNurseWarning(remaining<=60?`DOCTOR! Bed ${pending} needs you NOW!`:`Doctor, Bed ${pending} is deteriorating. Isn't there a more urgent patient to see?`);beep()}},[shiftSeconds,pending,emDeadline,active,done.length]);
useEffect(()=>{if(!pending)return;const id=setInterval(()=>beep(),15000);return()=>clearInterval(id)},[pending,mute]);
function beepRoutine(){if(mute)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=660;g.gain.value=.045;o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.13);setTimeout(()=>ctx.close(),350)}catch{}}
function append(s){setLog(v=>[...v,s].slice(-35))}
useEffect(()=>{logEnd.current?.scrollIntoView({block:'nearest',behavior:'smooth'})},[log,active]);
function openBed(b){if(pending&&pending!==b){setNurseWarning(`👩🏾‍⚕️ Nurse Aisha: Doctor! Bed ${pending} is deteriorating. Isn't there a more urgent patient to see?`);setNotice(`⚠️ Bed ${pending} needs urgent attention — you can still see Bed ${b}.`)}const em=pending===b;setActive({bed:b,em});setStation(false);setDraft('');setSbar('');setReg(false);setLog([em?`👩🏾‍⚕️ Nurse Aisha: Doctor, please come quickly. ${emergencies[b].start}`:b===7?'👩🏾‍⚕️ Nurse Aisha: John’s family is here at the bedside. Please talk with them about how he manages at home. Ask open questions — there is no fixed script.':`👩🏾‍⚕️ Nurse Aisha: Doctor, could you see ${patients[b-1].name}? We need to ${patients[b-1].job.toLowerCase()}.`]);if(em){setEmDeadline(null);setNurseWarning('');setStage(0);setAssessed({});setTreated(false);setNotice('🚨 Emergency: routine work paused. Assess and treat the patient now.')}else if(b===5){setLog(v=>[...v,'👩🏾‍⚕️ Nurse Aisha: Mo weighs 72 kg. He previously received 500 mL of sodium chloride 0.9% over one hour. Please review his fluid balance and bloods before prescribing.'])}else if(b===4){setLog(v=>[...v,'👩🏾‍⚕️ Nurse Aisha: Please review fluid status, urine output and the previous blood results.'])}}
function close(){setActive(null);setDraft('');setReg(false)}
function finishJob(){const b=active.bed;if(!done.includes(b)){setDone(v=>[...v,b]);setHistory(v=>[{bed:b,type:'Routine job',outcome:'Completed',time:clock},...v])}setGrave(v=>v.filter(x=>x!==b));append('Job completed. Documented in the clinical notes.');setNotice(`✓ Bed ${b}: routine job completed.`);close()}
function useEquipment(key){if(!active)return;const b=active.bed;if(b===10&&!active.em&&key==='abg'){if(copdStep===0){setCopdStep(1);append('🩺 You: I explain the ABG, check consent and perform arterial sampling using appropriate aseptic technique.\n👩🏾‍⚕️ Nurse Aisha: Sample collected safely and sent for analysis. ABG: pH 7.29, PaCO₂ 7.8 kPa, PaO₂ 7.5 kPa, HCO₃⁻ 27 mmol/L. Please interpret it before prescribing oxygen.');}else append('👩🏾‍⚕️ Nurse Aisha: The ABG has already been collected. Please interpret the result shown in the panel.');return}if(key==='request form'){setRequest([3,8].includes(b)?'xray':'blood');return}if(active.em){doAction(key);return}const sequence=procedureSequence[b];if(sequence){if([4,9].includes(b)&&!requests[b]){append('👩🏾‍⚕️ Nurse: Please complete the blood request form before collecting the sample.');setRequest('blood');return}const current=procedures[b]||0;const expected=sequence[current];if(key!==expected){append(`👩🏾‍⚕️ Nurse: You've selected ${key}. What should we prepare or do first? Think about the safe order of the procedure.`);return}setProcedures(v=>({...v,[b]:current+1}));append(`🩺 You: I'll use the ${key}.\n👩🏾‍⚕️ Nurse: ${key==='catheter'?'The catheter is being inserted using aseptic technique.':key==='tubes'?'Samples collected and labelled at the bedside.':`Done — ${key} ready.`}`);if(current+1===sequence.length){append(`👩🏾‍⚕️ Nurse: Samples labelled and sent. The laboratory results are now available: ${labResults[b]||'Results pending.'}`);if(b===4)append('🚨 Nurse Aisha: Potassium 5.7 mmol/L and creatinine 248 µmol/L — urgent ECG, reassessment and senior escalation are needed. Call Meddy Reg.');setSteps(v=>({...v,[b]:jobs[b].length}));if(!done.includes(b)){setDone(v=>[...v,b]);setHistory(v=>[{bed:b,type:'Routine job',outcome:'Procedure completed',time:clock},...v])}}return}doAction(key)}
function submitRequest(form){const b=active.bed;const isBlood=[4,9].includes(b);if(!isBlood){const test=form.test.toLowerCase(),history=form.clinical.toLowerCase(),question=form.question.toLowerCase();const missing=[];if(b===6){if(!/af|atrial|cardiac|palpitation|arrhythmia/i.test(form.clinical+' '+form.question))missing.push('include the AF indication');if(missing.length){append('👩🏾‍⚕️ Nurse Aisha: Please include the indication for the echo.');return}setRequests(v=>({...v,[b]:form}));setRequest(null);append('👩🏾‍⚕️ Nurse Aisha: Echocardiography request accepted. We will arrange the scan.');return}if(b===3&&!/chest|cxr/.test(test))missing.push('specify a chest X-ray');if(b===8&&!/hip|pelvis/.test(test))missing.push('specify the affected hip and/or pelvis');if(!/breath|chest|cough|hypox|fall|pain|fracture|pe|embol|tachy|injur/.test(history))missing.push('add relevant symptoms and examination findings');if(!/exclude|assess|confirm|fracture|pneumonia|alternative|pathology|cause/.test(question))missing.push('state a clear clinical question');if(missing.length){append(`👩🏾‍⚕️ Nurse Aisha: Radiology needs more detail: ${missing.join('; ')}. Please amend and resubmit.`);return}}setRequests(v=>({...v,[b]:form}));setRequest(null);append(`🩺 You: I've submitted ${form.test}.\n👩🏾‍⚕️ Nurse Aisha: ${isBlood?'The blood request is accepted. Please collect and label the samples before results can be released.':'Good request — the clinical details and question are clear. Radiology will review it.'}`);if(!isBlood){setSteps(v=>({...v,[b]:jobs[b].length}));setDone(v=>v.includes(b)?v:[...v,b]);setHistory(v=>[{bed:b,type:'Routine job',outcome:'Radiology request reviewed and accepted',time:clock},...v])}}

function doAction(raw){const action=raw.trim();if(!action)return;const t=action.toLowerCase();setDraft('');if(!active)return;append(`🩺 You: ${action}`);
const b=active.bed;
if(active.em&&b===7&&/(?:hello|hi|home|family|manage|support|social|carer)/i.test(t)){append('👩🏾‍⚕️ Nurse Aisha: John cannot speak or cough effectively. His routine social history is on hold — please manage the airway emergency.');return}
if(!active.em&&/fluid (?:status|balance)|hydration|urine output|input.?output|previous (?:bloods|results)|earlier (?:bloods|results)/i.test(t)&&[4,5].includes(b)){
 append(b===5?'👩🏾‍⚕️ Nurse Aisha: Weight 72 kg. Previous IV fluid: 500 mL sodium chloride 0.9% over one hour. Last 4 hours: 350 mL oral/IV input, 100 mL urine output. BP 108/66, HR 106, dry mucous membranes. Previous bloods: glucose 34, Na 151, K 4.2, urea 16 mmol/L.':'👩🏾‍⚕️ Nurse Aisha: Last 6 hours: 450 mL input, 120 mL urine output. BP 102/64, HR 104, dry mucous membranes. Previous bloods: creatinine 186 µmol/L (baseline 86), potassium 5.1 mmol/L. Please repeat U&Es.');return}
if(!active.em&&b===5&&/osmolal|hhs (?:help|hint|guidance)|fluid (?:guidance|prescrib)/i.test(t)){
 append('💙 Meddy: Calculated osmolality (mmol/kg) ≈ 2 × sodium + glucose + urea, all in mmol/L. With Na 151, glucose 34 and urea 16, this is 352 mOsm/kg. In HHS, monitor osmolality trends, fluid balance, electrolytes and clinical status closely; avoid overly rapid correction. Use the local JBDS HHS pathway and senior advice for fluid rates.');return}
if(/(?:can|could|may|please|let me|i(?:'d| would) like to|show me|review|look at|see|check|what (?:are|were))[^.!?]{0,75}(?:bloods|blood results|lab results|u.?e|fbc|crp|potassium|creatinine|electrolytes|abg)/i.test(t)){if(b===10&&!active.em&&copdStep===0){append('👩🏾‍⚕️ Nurse Aisha: We have not taken an ABG yet. Please use the ABG kit on the equipment trolley first.');return}if(!active.em&&[4,9].includes(b)&&(procedures[b]||0)<(procedureSequence[b]?.length||0)){append('👩🏾‍⚕️ Nurse Aisha: The new results are not available until the blood sample has been collected and sent. Previous results can be reviewed separately.');return}append(`👩🏾‍⚕️ Nurse Aisha: Of course, doctor. I've opened the latest results.\n🧪 RESULTS — ${labResults[b]||'No blood results have been returned yet. You can request investigations.'}`);if(b===4&&(!active.em)){append('🚨 Nurse Aisha: Potassium is 5.7 mmol/L with worsening AKI. Please urgently review the patient, obtain an ECG and contact Meddy Reg for advice.')}return}
if(/(?:can|could|may|please|let me|i(?:'d| would) like to|check|measure|what(?:'s| is)|tell me|take)[^.!?]{0,80}(?:respiratory rate|respirations|oxygen saturation|spo2|heart rate|pulse|blood pressure|temperature|observations|vital signs|blood glucose|blood sugar)/i.test(t)){append(`👩🏾‍⚕️ Nurse Aisha: Certainly. ${clinicalObservations[b]}`);if(active.em){const category=abc[stage]?.toLowerCase();if(category&&synonyms[category].test(t))setAssessed(v=>({...v,[category]:true}))}return}
if(/(?:hello|hi|good morning|good afternoon|how are you|my name is|i'm (?:the|a) doctor|i am (?:the|a) doctor)/i.test(t)){append(`🧑 ${patients[b-1].name}: Hello doctor. ${b===2?'I have been coughing and feeling feverish.':b===5?'I have been very thirsty and tired.':b===7?'I am not sure how I will manage at home.':'Thank you for coming to see me.'}`);return}
if(/(?:prescrib|start|chart|give|order)[^.!?]{0,90}(?:antibiotic|amoxicillin|doxycycline|clarithromycin|co.?amoxiclav)/i.test(t)&&b===2&&!active.em){setPrescription('antibiotic');append('👩🏾‍⚕️ Nurse Aisha: I’ll open the drug chart. Please check allergies and write the drug, dose, route, frequency and duration.');return}
if(/(?:prescrib|start|chart|give|order|plan)[^.!?]{0,90}(?:iv fluid|fluids|saline|sodium chloride|hartmann|crystalloid)/i.test(t)&&b===5&&!active.em){setPrescription('fluid');append('👩🏾‍⚕️ Nurse Aisha: I’ll open the fluid chart. Please specify the fluid, volume and rate.');return}
if(!active.em&&b===2&&/(?:antibiotic)/i.test(t)){setPrescription('antibiotic');append('👩🏾‍⚕️ Nurse Aisha: Please complete the prescription chart.');return}
if(!active.em&&b===5&&/(?:fluid|saline)/i.test(t)){setPrescription('fluid');append('👩🏾‍⚕️ Nurse Aisha: Please complete the IV fluid chart.');return}
if(!active.em&&b===2&&/allerg|penicillin|reaction/i.test(t)&&!/prescrib|chart|antibiotic/i.test(t)){append('👩🏻 Chessie Coff: I have no known drug allergies, doctor.');return}
if(!active.em&&b===6&&/echo|echocardiogra|ultrasound of.*heart/i.test(t)){append('👩🏾‍⚕️ Nurse Aisha: I have opened the echocardiography request. Please include the indication: atrial fibrillation and assessment of cardiac structure and function.');setRequest('echo');return}
if(!active.em&&b===7){
 const question=t.replace(/[^a-z0-9 ]/g,' ').trim();
 const topics=[[/walk|mobil|stairs|fall|getting around|move about|independen/, 'mobility', '👨🏻‍🦳 Relative: Dad uses a walking frame, but he has become unsteady and cannot manage the stairs alone.'],[/wash|dress|bath|toilet|personal|look after himself|self care/, 'personal', '👨🏻‍🦳 Relative: He needs help with washing, dressing and getting to the bathroom.'],[/meal|food|cook|eat|shop|nutrition/, 'meals', '👨🏻‍🦳 Relative: He struggles to cook or shop, so we bring meals over.'],[/medic|tablet|drug|remember|memory|confus|cognit/, 'medicines', '👨🏻‍🦳 Relative: He sometimes forgets medication and appointments. We help organise his tablets.'],[/home|carer|care|support|discharg|family|live|alone|safe/, 'support', '👨🏻‍🦳 Relative: He lives alone and we cannot provide round-the-clock care. We would appreciate an OT and social care assessment.']];
 const found=topics.find(([re])=>re.test(question));
 const openQuestion=/how (?:is|does|has|was)|tell me|describe|what (?:is|was|has|can|does)|could you|can you|please|more about|concern|worried|manage|usual|normally|day.to.day|daily|been like|recently|change|problem|difficult/.test(question);
 const chosen=found|| (openQuestion ? topics.find(x=>!socialTopics.includes(x[1]))||topics[4] : null);
 if(chosen){append(chosen[2]);const next=[...new Set([...socialTopics,chosen[1]])];setSocialTopics(next);setSteps(v=>({...v,[7]:Math.min(3,next.length)}));if(next.length>=3){append('👩🏾‍⚕️ Nurse Aisha: That gives us a useful picture of his baseline. We can document this and arrange OT/discharge planning.');setDone(v=>v.includes(7)?v:[...v,7]);setHistory(v=>[{bed:7,type:'Family conversation',outcome:'Baseline care needs discussed',time:clock},...v]);}return}
 append('👨🏻‍🦳 Relative: I am worried about how Dad will cope at home. You can ask me anything about his usual day or what has changed.');return
}
if(!active.em){const b=active.bed;if(b===10){append('👩🏾‍⚕️ Nurse Aisha: Please complete the ABG workflow shown alongside the patient. You can use the trolley and the interpretation choices.');return}if(/x.?ray|radiograph|request.*blood|request.*u.?e|blood form/i.test(t)&&[3,4,8,9].includes(b)){setRequest([3,8].includes(b)?'xray':'blood');append('👩🏾‍⚕️ Nurse: I’ve opened the request form. Please complete the clinical details.');return}if(/catheter|venepuncture|take blood|blood sample/i.test(t)&&[1,4,9].includes(b)){append('👩🏾‍⚕️ Nurse: Please select the equipment on the trolley in the correct order.');return}const i=steps[b]||0;const step=jobs[b]?.[i];if(!step){finishJob();return}const key=step[0];const pattern={catheter:/catheter|insert|lubricat|clean|aseptic/,balloon:/balloon|secure|drain|document/,allergy:/allerg|curb|severity/,antibiotic:/antibiot|amoxicillin|doxycycl|prescrib/,relative:/relative|family|daughter|son/,adl:/adl|activit|wash|dress|mobil|meal|medicat/,social:/social|carer|occupational|ot|discharg/,fluid:/fluid|hydration|urine|saline/,blood:/blood|fbc|clotting|group/,score:/blatchford|risk|score/,pain:/pain|analges|neurovascular/,oxygen:/oxygen|saturat/,abg:/abg|blood gas/,glucose:/glucose|sugar|osmolal/,ecg:/ecg|electrocardiogram/,echo:/echo|ultrasound/,xray:/x.?ray|radiograph/,observations:/observ|vitals|respirat/, 'u&e':/u.?e|creatinine|renal|potassium/, 'confirm identity':/identity|consent|explain/, 'hand hygiene':/hand|sterile|aseptic/}[key]||new RegExp(key,'i');if(pattern.test(t)){append(`👩🏾‍⚕️ Nurse Aisha: Thank you. ${step[1]}`);setSteps(v=>({...v,[b]:i+1}));if(i===jobs[b].length-1){setTimeout(()=>{},0);if(!done.includes(b)){setDone(v=>[...v,b]);setHistory(v=>[{bed:b,type:'Routine job',outcome:'Completed',time:clock},...v]);setNotice(`✓ ${patients[b-1].name}: job complete`)}setGrave(v=>v.filter(x=>x!==b))}}else append('Nurse: That action has not completed the current job. Try a relevant clinical action or ask Meddy for a hint.');return}
const issue=event.issue;const category=abc[stage].toLowerCase();if(/help|registrar|arrest team|resus team|senior/.test(t)){setReg(true);append('Nurse calls for senior assistance. Meddy Reg arrives at the bedside.');return}
if(/cough/.test(t)&&b===7&&!treated){append('John tries to cough, but his cough is ineffective and he cannot speak. The obstruction remains. Try a different intervention.');return}
if(/back blow|back slap|five back|5 back/.test(t)&&b===7){setTreated(true);append(event.result);return}
const interventions={oxygen:/oxygen|mask|non.?rebreath|reservoir/,monitor:/monitor|pulse ox/,glucose:/glucose|dextrose|sugar|finger.?prick/,ecg:/ecg|electrocardiogram|heart tracing/,iv:/iv|cannul|access|crossmatch/,abg:/abg|blood gas/,warm:/warm|blanket|rewarm/};let didIntervene=false;for(const [key,re]of Object.entries(interventions)){if(re.test(t)){didIntervene=true;if(key===event.treatment||(b===5&&key==='glucose')){setTreated(true);append(event.result)}else append(`${key.toUpperCase()} action performed. Continue assessing and treating the primary problem.`);break}}if(didIntervene)return;
if(synonyms[category].test(t)){setAssessed(v=>({...v,[category]:true}));const detail={airway:b===7?'Airway obstructed; ineffective cough.':'Airway currently patent; monitor for deterioration.',breathing:`RR ${event.ob.rr}/min, SpO₂ ${treated?Math.min(98,event.ob.spo2+9):event.ob.spo2}%.`,circulation:`HR ${event.ob.hr}/min, BP ${event.ob.bp}.`,disability:b===5?'Confused; capillary glucose 2.4 mmol/L.':'Assess AVPU/GCS and capillary glucose.',exposure:b===8?'Core temperature 33°C.':'No immediate external bleeding; complete temperature and skin assessment.'};append(`${abc[stage]}: ${detail[category]}`);return}append(`No useful change following “${action}”. Assess ${abc[stage]} or select an appropriate intervention. Meddy can help.`)}
function nextStage(){if(!assessed[abc[stage].toLowerCase()]){append(`Assess ${abc[stage]} by mentioning one or two relevant checks (for example, respiratory rate or breath sounds for Breathing). You can intervene immediately if needed.`);return}if(stage===4){if(!treated){append('You have completed the assessment, but the immediate problem still needs treatment. Select an appropriate intervention.');return}append('ABCDE completed and the immediate threat addressed. Reassess and give SBAR to Meddy Reg.');setStage(5)}else setStage(v=>v+1)}
function hint(){if(active&&!active.em&&active.bed===5){append('💡 Meddy hint: For HHS, calculate osmolality as 2 × Na + glucose + urea (mmol/L). Check the trend, weight, fluid balance and previous fluids. Use the local HHS protocol before choosing a rate.');return}const msg=active?.em?`Consider what you would assess in ${abc[Math.min(stage,4)]}, and whether the patient needs an immediate intervention.`:`Think about the next clinical step for ${patients[active.bed-1].diagnosis}. What information or equipment would help?`;append(`💡 Meddy hint: ${msg}`)}
function finishEmergency(){if(stage!==5)return;if(sbar.trim().length<25){append('Meddy Reg: Please provide an SBAR handover covering the situation, background, assessment and recommendation.');return}const b=active.bed;setRescued(v=>v.includes(b)?v:[...v,b]);setHistory(v=>[{bed:b,type:'Emergency',outcome:event.result,time:clock,sbar},...v]);setGrave(v=>v.filter(x=>x!==b));setPending(null);setEmDeadline(null);setEmIndex(v=>v+1);setCompleteAt(done.length);setCooldown(true);setTimeout(()=>setCooldown(false),16000);setNotice(`🎉 ${patients[b-1].name} stabilised! ${event.token} added to your wallet. Complete two routine jobs before the next bleep.`);close();setTab('wallet')}
function fail(){const b=active.bed;if(active.em){setPending(null);setEmDeadline(null);setEmIndex(v=>v+1);setCompleteAt(done.length);setCooldown(true);setTimeout(()=>setCooldown(false),12000)}setGrave(v=>v.includes(b)?v:[...v,b]);setHistory(v=>[{bed:b,type:active.em?'Emergency':'Routine job',outcome:'Attempt ended — retry available',time:clock},...v]);setNotice(`Bed ${b} is in the graveyard. You can retry the scenario.`);close()}
function retry(b){setGrave(v=>v.filter(x=>x!==b));setSteps(v=>({...v,[b]:0}));setTab('jobs');if(emergencies[b]){setPending(b);setEmDeadline(null);setActive({bed:b,em:true});setStage(0);setAssessed({});setTreated(false);setLog([`👩🏾‍⚕️ Nurse Aisha: We're trying this emergency again. ${emergencies[b].start}`]);setReg(false)}else openBed(b)}
function speakAction(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){append('👩🏾‍⚕️ Nurse: Voice recognition is unavailable in this browser. Please type what you would like to say.');return}const r=new SR();r.lang='en-GB';r.interimResults=false;r.continuous=false;r.onresult=e=>{const words=Array.from(e.results).map(x=>x[0].transcript).join(' ');setDraft(words);doAction(words)};r.onerror=()=>append('👩🏾‍⚕️ Nurse: I could not hear that clearly. Please try again or type your question.');r.start()}
function startVoice(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){append('Speech transcription is not supported here. Try Chrome or type your SBAR.');return}const r=new SR();speech.current=r;r.lang='en-GB';r.continuous=true;r.interimResults=true;let final=sbar;r.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal)final+=' '+e.results[i][0].transcript;else interim+=e.results[i][0].transcript}setSbar((final+' '+interim).trim())};r.onend=()=>setListening(false);r.start();setListening(true)}
return <><header><div className="brand"><span className="logo">M</span><b>MediWard</b><small>{mode.toUpperCase()} MODE</small></div><div className="headtools"><b>🕒 {clock} {minute>=540?'🌙':'☀️'}</b><button onClick={()=>setMute(v=>!v)}>{mute?'🔇 Muted':'🔊 Sound'}</button><button onClick={()=>location.reload()}>↻ Restart</button></div></header>{!started?<section className="welcome"><span className="biglogo">M</span><h1>Welcome to MediWard</h1><p>A day on the ward. Complete clinical jobs, manage emergencies and earn achievements.</p><label>Difficulty <select value={mode} onChange={e=>setMode(e.target.value)}><option value="easy">Easy mode</option><option value="hard">Hard mode</option></select></label><label>Your character <select value={avatar} onChange={e=>setAvatar(e.target.value)}>{['👩🏽‍⚕️','👨🏿‍⚕️','👩🏻‍⚕️','👨🏼‍⚕️','👩🏾‍⚕️','👨🏻‍⚕️'].map(x=><option key={x}>{x}</option>)}</select></label><button className="primary" onClick={()=>setStarted(true)}>Start shift →</button><p className="muted">Educational prototype; clinical content requires expert review before formal teaching use.</p></section>:<div className="layout"><main><div className="wardheading"><h2>Ward 1 <small>Medical assessment unit</small></h2><b>{done.length}/10 jobs complete</b></div><WalkWard patients={patients} pending={pending} done={done} avatar={avatar} clock={clock} minute={minute} onBed={openBed} onStation={()=>setStation(true)}/><p className="muted">Walk using WASD or arrow keys; E to interact. Click a bed to walk towards it. First emergency after roughly two minutes.</p></main><aside><nav>{[['jobs','📋 Jobs'],['grave','🪦 Graveyard'],['wallet','🏆 Wallet'],['history','📖 History']].map(([k,label])=><button key={k} className={tab===k?'active':''} onClick={()=>setTab(k)}>{label}</button>)}</nav><div className="side">{tab==='jobs'?<><h3>Today's jobs</h3>{pending&&<button className="bleep" onClick={()=>openBed(pending)}>🚨 ATTEND NOW — Bed {pending}<small>{emergencies[pending].title}</small></button>}{patients.map(p=><button key={p.bed} className="job" onClick={()=>openBed(p.bed)}><b>{p.bed}</b><span>{p.name}<small>{p.job}</small></span>{done.includes(p.bed)?'✓':'→'}</button>)}<p className="muted">{!pending?emIndex===0?'First emergency around two minutes into the shift.':`Next emergency after ${Math.max(0,2-(done.length-completeAt))} more routine jobs.`:'Attend the urgent patient.'}</p></>:tab==='grave'?<><h3>Graveyard</h3>{grave.length?grave.map(b=><button className="job" key={b} onClick={()=>retry(b)}>🪦 Bed {b} · Retry ↻</button>):'No failed attempts.'}</>:tab==='wallet'?<><h3>Achievement wallet</h3>{rescued.length?rescued.map(b=><p key={b}>{emergencies[b].token} Bed {b} — rescued</p>):'No awards yet.'}</>:<><h3>Clinical history</h3>{history.length?history.map((h,i)=><div className="history" key={i}><b>{h.time} · Bed {h.bed} · {h.type}</b><p>{h.outcome}</p>{h.sbar&&<details><summary>SBAR handover</summary>{h.sbar}</details>}</div>):'No activity yet.'}</>}</div></aside></div>}{started&&pending&&emDeadline!==null&&<div className="emergency-clock">🚨 Bed {pending} needs urgent assessment · {Math.floor(Math.max(0,emDeadline-shiftSeconds)/60)}:{String(Math.max(0,emDeadline-shiftSeconds)%60).padStart(2,'0')} remaining <button onClick={()=>openBed(pending)}>Attend</button></div>}{started&&mode==='hard'&&routineBleeps.length>0&&<div className="routine-bleep-list">{routineBleeps.slice(0,2).map(q=><div key={q.id}>📟 {q.text} <button onClick={()=>setRoutineBleeps(v=>v.filter(x=>x.id!==q.id))}>Dismiss</button></div>)}</div>}{notice&&<div className="toast" role="alert">{notice}<button onClick={()=>setNotice('')}>×</button></div>}{station&&<div className="overlay"><section className="station"><button className="close" onClick={()=>setStation(false)}>✕</button><h2>👩🏾‍⚕️ Nurse station</h2><p>Nurse Aisha: “{pending?`Doctor, Bed ${pending} needs you now!`:'Can you help with the outstanding jobs? We have patients waiting.'}”</p><p>Nurse Oliver: “{pending?'I can bring the emergency trolley and monitor.':'Bed 4 needs bloods, and Bed 6 is waiting for an ECG.'}”</p><button onClick={()=>{setStation(false);if(pending)openBed(pending)}}>{pending?'Attend emergency':'Return to ward'}</button></section></div>}{active&&<div className="bedside-full">{pending&&active.bed!==pending&&<div className="priority-warning">🚨 {nurseWarning||`Nurse Aisha: Doctor, Bed ${pending} is an emergency. Isn't there a more urgent patient to see?`} <button onClick={()=>openBed(pending)}>Go to Bed {pending}</button></div>}<div className="bedside-top"><div><small>{active.em?'🚨 EMERGENCY — ROUTINE JOB PAUSED':'CLINICAL JOB'} · BED {active.bed}</small><h2>{activePatient.name}</h2><p>{active.em?event.title:activePatient.job}</p>{!active.em&&<div className="patient-jobs"><b>📋 Jobs for this patient</b>{jobs[active.bed].map((j,i)=><div key={i}>• {j[1]}</div>)}</div>}</div><button onClick={close}>✕ Return to ward</button></div><div className="bedside-columns"><div className="visual-panel"><div className="hospital-scene"><div className="scene-window">{minute>=540?'🌙':'☀️'}</div><div className="scene-monitor"><b>♥ {active.em?event.ob.hr:86}</b><svg viewBox="0 0 230 60"><polyline points="0,34 35,34 43,25 51,45 61,5 72,53 83,34 115,34 123,25 131,45 141,5 152,53 163,34 230,34" fill="none" stroke="#64f0a3" strokeWidth="3"/></svg><small>SpO₂ {active.em?(treated?Math.min(98,event.ob.spo2+9):event.ob.spo2):97}%</small></div><div className="hospital-bed"><div className="bed-pillow"/><div className="patient-body"><div className="patient-face">{activePatient.avatar}</div><div className={'patient-blanket '+(active.em&&!treated?'unwell':'')}/></div></div><div className="bed-floor"/>{reg&&<div className="reg-character"><Meddy large/><b>Meddy Reg</b></div>}</div><div className="vitals"><span>HR <b>{active.em?event.ob.hr:86}</b></span><span>SpO₂ <b>{active.em?(treated?Math.min(98,event.ob.spo2+9):event.ob.spo2):97}%</b></span><span>BP <b>{active.em?event.ob.bp:'120/75'}</b></span><span>RR <b>{active.em?event.ob.rr:18}</b></span></div><h3>Equipment and charts</h3>{!active.em&&active.bed===6&&<button className="primary" onClick={()=>setRequest('echo')}>🫀 Request echocardiogram</button>}{!active.em&&[2,5].includes(active.bed)&&<button className="primary" onClick={()=>setPrescription(active.bed===2?'antibiotic':'fluid')}>{active.bed===2?'💊 Open drug chart':'💧 Open IV fluid chart'}</button>}<div className="equipment">{(active.em?equipment:(routineEquipment[active.bed]||equipment)).map(([emoji,label,key])=><button key={key} onClick={()=>useEquipment(key)}><span>{emoji}</span>{label}</button>)}</div></div><div className="clinical-panel"><div className="clinical-head"><h3>{active.em?'ABCDE assessment':'Routine clinical task'}</h3><button onClick={()=>{setReg(true);append('💙 Meddy Reg: I have come to the bedside. '+(active?.em?event.hint:active.bed===5?'Mo weighs 72 kg and previously received 500 mL 0.9% saline over an hour. His calculated osmolality is 352 mOsm/kg (2 × Na + glucose + urea). Review fluid balance, electrolytes and the local HHS pathway; avoid rapid osmolality shifts.':active.bed===4?'Potassium 5.7 mmol/L in worsening AKI warrants prompt ECG, repeat assessment and urgent escalation under local hyperkalaemia guidance.':jobs[active.bed]?.[steps[active.bed]||0]?.[1]||'Review the clinical plan and document your findings.'))}}>💙 Call Meddy Reg</button></div>{!active.em&&active.bed===10&&<div className="copd-workflow"><h3>🫁 COPD — bedside workflow</h3><p><b>1. Obtain observations</b> — Nurse Aisha: RR 30/min, SpO₂ 86% on air, HR 112/min, BP 138/78. The patient is breathless.</p><p><b>2. ABG sampling</b> — {copdStep===0?'Click ABG on the equipment trolley to collect the sample.':'✓ Sample collected. pH 7.29, PaCO₂ 7.8 kPa, PaO₂ 7.5 kPa, HCO₃⁻ 27 mmol/L.'}</p>{copdStep>=1&&<><p><b>3. Interpret the ABG</b></p><div className="copd-options">{['Acute hypercapnic respiratory acidosis','Metabolic alkalosis','Normal arterial blood gas'].map((a,i)=><button key={a} disabled={copdStep>=2} onClick={()=>{if(i===0){setCopdStep(2);append('👩🏾‍⚕️ Nurse Aisha: Correct — this is hypercapnic respiratory acidosis. Please choose the controlled oxygen saturation target and arrange senior review for possible ventilatory support.')}else append('💡 Meddy: Look at the low pH and raised carbon dioxide. What type of acid-base disturbance does that suggest?')}}>{a}</button>)}</div></>}{copdStep>=2&&<><p><b>4. Select oxygen saturation target</b></p><div className="copd-options">{['88–92%','94–98%','100%'].map((a,i)=><button key={a} disabled={copdStep>=3} onClick={()=>{if(i===0){setCopdStep(3);setDone(v=>v.includes(10)?v:[...v,10]);setHistory(v=>[{bed:10,type:'Routine job',outcome:'ABG interpreted and controlled oxygen target selected',time:clock},...v]);append('👩🏾‍⚕️ Nurse Aisha: Target 88–92% selected. We will titrate controlled oxygen, repeat ABGs and urgently involve the senior team regarding hypercapnic respiratory failure.')}else append('👩🏾‍⚕️ Nurse Aisha: That is not the usual target for this patient at risk of hypercapnic respiratory failure. Reconsider the target range.')}}>{a}</button>)}</div></>}{copdStep===3&&<p>✓ Workflow complete — review and escalate the respiratory acidosis.</p>}</div>}{active.em?<><div className="abc-tabs">{abc.map((a,i)=><button key={a} disabled={i>stage} className={i===stage?'selected':assessed[a.toLowerCase()]?'checked':''} onClick={()=>setStage(i)}>{a[0]}{assessed[a.toLowerCase()]?' ✓':''}</button>)}</div><p className="stage-label">{stage<5?`${abc[stage]} — assess, intervene and reassess`:'ABCDE complete — SBAR handover'}</p>{stage===5?<><textarea value={sbar} onChange={e=>setSbar(e.target.value)} placeholder="Situation, Background, Assessment, Recommendation…" rows={4}/><div className="action-row"><button onClick={listening?()=>{speech.current?.stop();setListening(false)}:startVoice}>{listening?'⏹ Stop recording':'🎙 Speak SBAR'}</button><button className="primary" onClick={finishEmergency}>Finish handover · collect {event.token}</button></div></>:<button className="primary" onClick={nextStage}>Complete {abc[stage]} assessment →</button>}</>:<p className="muted">Talk to the patient or nurse naturally, request results, or use the equipment and clinical charts. Meddy can help if you're unsure.</p>}{(!active.em||stage!==5)&&<div className="action-row"><input placeholder="e.g. ‘Hello, may I check your respiratory rate?’ or ‘Nurse, can I see the bloods?’" value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>e.key==='Enter'&&doAction(draft)}/><button onClick={speakAction} title="Speak to the patient or nurse">🎙 Speak</button><button className="primary" onClick={()=>doAction(draft)}>Say / do →</button></div>}{!active.em&&done.includes(active.bed)&&<button className="primary" onClick={finishJob}>✓ Finish job</button>}<h3>💬 Bedside conversation</h3><div className="clinical-log chat-log" aria-live="polite" role="log">{log.map((l,i)=><div className="chat-bubble" key={i}>{l.split("\n").map((line,j)=><p key={j}>{line}</p>)}</div>)}<div ref={logEnd}/></div><div className="action-row"><button onClick={hint}>💡 Ask Meddy for a clue</button><button onClick={fail}>End attempt · retry later</button></div>{reg&&<div className="reg-note"><Meddy/><span>Meddy Reg is at the bedside. Use the guidance above to decide what to do next.</span></div>}</div></div></div>}{prescription&&active&&<PrescriptionChart kind={prescription} patient={activePatient} onClose={()=>setPrescription(null)} onSubmit={v=>{const b=active.bed;setPrescribed(x=>({...x,[b]:v}));setPrescription(null);if(prescription==='antibiotic'){const drug=v.drug.toLowerCase();const dose=v.dose.toLowerCase();const validDrug=/amoxicillin|doxycycline|clarithromycin/.test(drug);const validDose=(drug.includes('amoxicillin')&&/500\s*mg/.test(dose))||(drug.includes('doxycycline')&&/100|200/.test(dose))||(drug.includes('clarithromycin')&&/500\s*mg/.test(dose));if(!validDrug||!validDose){append('💙 Meddy Reg: This prescription needs review. Check the antibiotic choice, dose, allergy history, severity, renal function and current local CAP guidance. You can amend the chart.');return}append(`👩🏾‍⚕️ Nurse Aisha: I've received your prescription for ${v.drug} ${v.dose} ${v.route}, ${v.frequency}. Please check it against our local CAP guideline and document review.`)}else{const vol=Number(v.volume),hours=Number(v.time);if(!Number.isFinite(hours)||hours<=0||vol>2000){append('💙 Meddy Reg: Please review the volume and infusion duration, assess fluid status and follow the local HHS pathway.');return}append(`👩🏾‍⚕️ Nurse Aisha: The chart reads ${v.volume} mL ${v.fluid} over ${v.time} hours (${Math.round(vol/hours)} mL/hour). Please reassess observations, sodium, potassium and fluid balance.`)}setSteps(x=>({...x,[b]:jobs[b].length}));setDone(x=>x.includes(b)?x:[...x,b]);setHistory(x=>[{bed:b,type:'Prescription',outcome:'Chart completed for review',time:clock},...x]);setNotice('Prescription chart completed — review with local guidelines.')}}/>}{request&&active&&<RequestForm kind={request} patient={activePatient} onClose={()=>setRequest(null)} onSubmit={submitRequest}/>}</>}
createRoot(document.getElementById('root')).render(<App/>);
